"""Quadratic and hash-based versions of the same tasks. Each function returns its answer and a count of the
basic steps it took (comparisons or hash lookups), so growth can be measured exactly, without a stopwatch."""
from __future__ import annotations

from collections import Counter, defaultdict


def has_duplicate_quadratic(items: list) -> tuple[bool, int]:
    """Compare every pair: n(n-1)/2 comparisons when there is no duplicate."""
    comparisons = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            comparisons += 1
            if items[i] == items[j]:
                return True, comparisons
    return False, comparisons


