def two_sum_quadratic(nums: list[int], target: int) -> tuple[tuple[int, int] | None, int]:
    comparisons = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            comparisons += 1
            if nums[i] + nums[j] == target:
                return (i, j), comparisons
    return None, comparisons


