"""A singly linked list with head and tail references."""
from __future__ import annotations

from typing import Any, Iterator


class Node:
    __slots__ = ("value", "next")

    def __init__(self, value: Any, next: Node | None = None) -> None:
        self.value, self.next = value, next


class LinkedList:
    def __init__(self, values=()) -> None:
        self.head: Node | None = None
        self.tail: Node | None = None
        self.size = 0
        for v in values:
            self.append(v)

    def __iter__(self) -> Iterator[Any]:
        node = self.head
        while node:
            yield node.value
            node = node.next

    def __len__(self) -> int:
        return self.size

    def push_front(self, value: Any) -> None:
        self.head = Node(value, self.head)
        if self.tail is None:
            self.tail = self.head
        self.size += 1

    def append(self, value: Any) -> None:
        """O(1), thanks to the tail reference."""
        node = Node(value)
        if self.tail is None:
            self.head = self.tail = node
        else:
            self.tail.next = node
            self.tail = node
        self.size += 1

    def pop_front(self) -> Any:
        if self.head is None:
            raise IndexError("pop from an empty list")
        node = self.head
        self.head = node.next
        if self.head is None:
            self.tail = None
        self.size -= 1
        return node.value

    def remove(self, value: Any) -> bool:
        """Remove the first node holding value; return whether one was found. Keep tail and size correct.
        A dummy node in front of the head means removing the head needs no special case."""
        raise NotImplementedError("TODO")

    def reverse(self) -> None:
        """Reverse in place in one pass, with O(1) extra space: previous, current and next references."""
        raise NotImplementedError("TODO")

    def middle(self) -> Any:
        """The middle value (the second of two middles for an even length), using fast and slow pointers."""
        if self.head is None:
            raise IndexError("empty list")
        raise NotImplementedError("TODO: move fast two steps and slow one step until fast runs out")


