    """Two pointers from both ends of a sorted list: the indices of a pair adding up to target, or None."""
    lo, hi = 0, len(sorted_nums) - 1
    while lo < hi:
        s = sorted_nums[lo] + sorted_nums[hi]
        if s == target:
            return lo, hi
        if s < target:
