"""A binary search tree. Every method is iterative, so a degenerate tree (a long chain) can't hit Python's
recursion limit."""
from __future__ import annotations

from collections import deque
from typing import Any, Iterator


class Node:
    __slots__ = ("key", "left", "right")

    def __init__(self, key: Any) -> None:
        self.key, self.left, self.right = key, None, None


class BST:
    def __init__(self, keys=()) -> None:
        self.root: Node | None = None
        self.size = 0
        for k in keys:
            self.insert(k)

    def insert(self, key: Any) -> bool:
        """Add key; return False if it was already there."""
        raise NotImplementedError("TODO: walk down from the root, going left for smaller keys and right for larger")

    def __contains__(self, key: Any) -> bool:
        node = self.root
        while node is not None and node.key != key:
            node = node.left if key < node.key else node.right
        return node is not None

    def inorder(self) -> Iterator[Any]:
        """Keys in sorted order, with an explicit stack instead of recursion."""
        raise NotImplementedError("TODO: go left as far as possible, pushing nodes; pop, yield, then go right")

    def height(self) -> int:
        """Number of levels (0 for an empty tree), by breadth-first search."""
        levels, frontier = 0, deque([self.root] if self.root else [])
        while frontier:
            levels += 1
            for _ in range(len(frontier)):
                n = frontier.popleft()
                frontier.extend(c for c in (n.left, n.right) if c is not None)
        return levels

    def range_query(self, lo: Any, hi: Any) -> list[Any]:
        """Keys k with lo <= k <= hi, in order."""
        return [k for k in self.inorder() if lo <= k <= hi]

    def delete(self, key: Any) -> bool:
