"""A binary min-heap stored in a list: the children of index i are 2i + 1 and 2i + 2, its parent (i - 1) // 2.
`swaps` counts element moves, to compare building a heap by pushes with heapify."""
from __future__ import annotations

from typing import Any


class MinHeap:
    def __init__(self) -> None:
        self.a: list[Any] = []
        self.swaps = 0

    def __len__(self) -> int:
        return len(self.a)

    def peek(self) -> Any:
        if not self.a:
            raise IndexError("peek at an empty heap")
        return self.a[0]

    def _sift_up(self, i: int) -> None:
        raise NotImplementedError("TODO: while i > 0 and a[i] < its parent, swap them (count each swap)")

    def _sift_down(self, i: int) -> None:
        raise NotImplementedError("TODO: swap with the smaller child while that child is smaller (count swaps)")

    def push(self, item: Any) -> None:
        self.a.append(item)
        self._sift_up(len(self.a) - 1)

    def pop(self) -> Any:
        if not self.a:
            raise IndexError("pop from an empty heap")
        last = self.a.pop()
        if not self.a:
            return last
        top, self.a[0] = self.a[0], last
        self._sift_down(0)
        return top

    @classmethod
    def heapify(cls, items) -> "MinHeap":
        """Build a heap in O(n): sift down every parent, from the last one back to the root."""
        h = cls()
        h.a = list(items)
        for i in range(len(h.a) // 2 - 1, -1, -1):
            h._sift_down(i)
        return h


def top_k(items, k: int) -> list:
    """The k largest items, largest first, in O(n log k): a min-heap of the best k seen so far."""
    import heapq
    best: list = []
    for x in items:
        if len(best) < k:
            heapq.heappush(best, x)
        elif x > best[0]:
            heapq.heapreplace(best, x)
    return sorted(best, reverse=True)

