"""Graph algorithms on adjacency lists: {vertex: {neighbour: weight}}."""
from __future__ import annotations

import csv
import heapq
from collections import deque

Graph = dict[str, dict[str, float]]


def load(path: str, directed: bool = False) -> Graph:
    g: Graph = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            a, b, w = row["from"], row["to"], float(row["minutes"])
            g.setdefault(a, {})[b] = w
            g.setdefault(b, {})
            if not directed:
                g[b][a] = w
    return g


def path_to(prev: dict[str, str | None], goal: str) -> list[str]:
    """Walk the predecessor map back from goal; [] if goal was never reached."""
    if goal not in prev:
        return []
    path, node = [], goal
    while node is not None:
        path.append(node)
        node = prev[node]
    return path[::-1]


