"""Recursion, memoisation and dynamic programming."""
from __future__ import annotations

from functools import cache


def fib_naive(n: int, calls: list[int]) -> int:
    calls[0] += 1
    return n if n < 2 else fib_naive(n - 1, calls) + fib_naive(n - 2, calls)


def fib_memo(n: int) -> tuple[int, int]:
    """fib(n) with functools.cache; returns (value, how many distinct values were computed)."""
    computed = [0]

    @cache
    def f(k: int) -> int:
        computed[0] += 1
        return k if k < 2 else f(k - 1) + f(k - 2)

    return f(n), computed[0]


def greedy_coins(coins: list[int], amount: int) -> list[int]:
    """Always take the largest coin that fits: fast, and wrong for some coin systems."""
    out = []
    for c in sorted(coins, reverse=True):
        while amount >= c:
            out.append(c)
            amount -= c
    return out if amount == 0 else []


